    public static bool PointInRect(Point* p, Rect* r)
    {
        return (
            (p) != null
            && (r) != null
            && (p->X >= r->X)
            && (p->X < (r->X + r->W))
            && (p->Y >= r->Y)
            && (p->Y < (r->Y + r->H))
        )
            ? true
            : false;
    }

